CREATE TABLE users (id BIGSERIAL PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(180) UNIQUE NOT NULL, phone VARCHAR(30), password VARCHAR(255) NOT NULL, role VARCHAR(30) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE books (id BIGSERIAL PRIMARY KEY, isbn VARCHAR(40) UNIQUE, title VARCHAR(255) NOT NULL, author VARCHAR(255) NOT NULL, category VARCHAR(100), description TEXT, online_available BOOLEAN NOT NULL DEFAULT FALSE, digital_content TEXT, total_copies INT NOT NULL DEFAULT 0, available_copies INT NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE issues (id BIGSERIAL PRIMARY KEY, book_id BIGINT NOT NULL REFERENCES books(id), user_id BIGINT NOT NULL REFERENCES users(id), issued_at DATE NOT NULL, due_date DATE NOT NULL, returned_at DATE, fine NUMERIC(12,2) NOT NULL DEFAULT 0, status VARCHAR(30) NOT NULL);
CREATE TABLE notifications (id BIGSERIAL PRIMARY KEY, user_id BIGINT NOT NULL REFERENCES users(id), channel VARCHAR(20) NOT NULL, subject VARCHAR(255), message TEXT NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_issue_user ON issues(user_id); CREATE INDEX idx_issue_due ON issues(due_date); CREATE INDEX idx_issue_status ON issues(status); CREATE INDEX idx_books_title ON books(title);
